import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def isfib(v):
    a = 1
    b = 1
    while b < v:
        a, b = b, a + b
    return b == v
best = 0
cur = 0
for x in a:
    if isfib(x):
        cur += 1
        if cur > best:
            best = cur
    else:
        cur = 0
print(best)

